// サマリの表示分岐 (run_id・audience の上書き・premise 対象外・order 無し・depends_on)
// を固定する。実装済みの挙動の固定 (退行防止)。
func TestReviewTriageSummaryRenderBranches(t *testing.T) {
	src := `runs:
  - date: "2026-08-30"
    skill: code-review
    run_id: run-xyz
    model: opus-5
    scope: incremental
    head: abc1234
    findings:
      - id: 1
        file: docs/foo.md
        summary: 上書きの例
        category: test
        audience: operator
        audience_initial: developer
        consequence:
          condition: c
          who: operator
          what: w
          detectability: d
        premise_check:
          stages: none
          result: skipped
        verdict: held
        verdict_reason: H2
      - id: 2
        file: docs/bar.md
        summary: 採択
        category: test
        audience: developer
        consequence:
          condition: c
          who: developer
          what: w
          detectability: d
        premise_check:
          stages: A
          result: verified
        verdict: adopted
        verdict_reason: A2
      - id: 3
        file: docs/baz.md
        summary: 上書きしない例
        category: test
        audience: developer
        audience_initial: developer
        consequence:
          condition: c
          who: developer
          what: w
          detectability: d
        premise_check:
          stages: A
          result: verified
        verdict: adopted
        verdict_reason: A2
    plans:
      - problem_id: P1
        cause: c1
        finding_ids: [2]
        approach: a1
        sha: ""
        status: pending
      - problem_id: P2
        cause: c2
        finding_ids: [2]
        approach: a2
        order: 2
        depends_on: [P1]
        sha: abc9999
        status: done
`
	summary, err := renderReviewTriageSummary(reviewTriageDir+"feat-x.yaml", []byte(src))
	if err != nil {
		t.Fatalf("サマリの生成に失敗: %v", err)
	}
	for _, want := range []string{
		"(run-xyz)",            // run_id の表示
		"developer → operator", // audience の上書きの表示
		"| 対象外 |",              // premise stages none のセル (summary の語との誤一致を避けて列で照合)
		"| P1 | c1 | #2 | a1 | — | 未着手 | — |",               // order 無しの行全体 (他列の — との誤一致を避ける)
		"| P2 | c2 | #2 | a2 | 2 (P1 の後) | 済 | `abc9999` |", // depends_on と sha 真側の行全体
	} {
		if !strings.Contains(summary, want) {
			t.Fatalf("%q がサマリに無い:\n%s", want, summary)
		}
	}
	// 偽側: audience_initial == audience の指摘 (id 3) には上書きの矢印を出さない。
	if strings.Count(summary, "→") != 1 {
		t.Fatalf("上書きの矢印は 1 箇所 (id 1) だけのはず:\n%s", summary)
	}
}

// 循環する plan と循環しない plan が混在しても、循環だけが報告される。
func TestReviewTriageRecordMixedCyclePlans(t *testing.T) {
