// 既存の記録に、構造を持つキーの値が null の形があるか。
func TestZZProbeNullInExistingRecords(t *testing.T) {
	files, _ := filepath.Glob("/Users/akima/workspace/claude-plugins/docs/review-triage/*.yaml")
	want := map[string]bool{"plan_ref": true, "investigation": true, "consequence": true, "premise_check": true, "attrs": true, "plans": true, "findings": true, "gates_fired": true, "depends_on": true, "options": true, "notes": true}
	for _, f := range files {
		data, _ := os.ReadFile(f)
		var root yaml.Node
		if err := yaml.Unmarshal(data, &root); err != nil {
			t.Fatal(err)
		}
		var walk func(n *yaml.Node)
		walk = func(n *yaml.Node) {
			if n.Kind == yaml.MappingNode {
				for i := 0; i+1 < len(n.Content); i += 2 {
					k, v := n.Content[i], n.Content[i+1]
					if want[k.Value] && v.Kind == yaml.ScalarNode && v.Tag == "!!null" {
						t.Logf("%s:%d %s は null", filepath.Base(f), k.Line, k.Value)
					}
				}
			}
			for _, c := range n.Content {
				walk(c)
			}
		}
		walk(&root)
	}
}

// plan_ref が null のとき検査は何を言うか (plans がある回 / plans が無い最後の回)。
func TestZZProbeNullPlanRef(t *testing.T) {
	withPlans := strings.Replace(validRecordYAML, "        verdict_reason: ゲート 0 件で採択 (A2)\n",
		"        verdict_reason: ゲート 0 件で採択 (A2)\n        plan_ref:\n", 1)
	withPlans = strings.Replace(withPlans, "finding_ids: [1]", "finding_ids: [1]", 1)
	files, read := recordFiles(t, withPlans)
	fmt.Println("plans あり + plan_ref null:", reviewTriageRecordProblems(files, read))
	// plans を消して被覆の免除下に置く
	noPlans := withPlans[:strings.Index(withPlans, "    plans:")] + "    notes: fix 前。\n"
	files, read = recordFiles(t, noPlans)
	fmt.Println("plans なし (最後の回) + plan_ref null:", reviewTriageRecordProblems(files, read))
	// plans で覆われていない採択 + plan_ref null
	uncovered := strings.Replace(withPlans, "finding_ids: [1]", "finding_ids: [1]", 1)
	_ = uncovered
}
